"""C spelling helpers shared by the C emitters.

The emitters write code already in the repository's clang-format style
(`.clang-format`: LLVM base, 4-space indent, 100 columns, parameters packed
and aligned after the open parenthesis), so the formatter hook never rewrites a
generated file and the drift check stays byte-exact.
"""

from __future__ import annotations

import textwrap

from .model import SCALARS, Api, Field, Function, Param

COLUMNS = 100
BANNER = (
    "GENERATED by scripts/codegen/vmafx-api.py from core/api/vmafx.toml (ADR-1852).\n"
    "Do not edit: change the definition and run `python3 scripts/codegen/vmafx-api.py --write`."
)
NULLPTR_BEGIN = (
    "/* NOLINTBEGIN(modernize-use-nullptr): C translation unit. The fork builds C as\n"
    " * C23, where clang-tidy also proposes the `nullptr` keyword, but MSVC's\n"
    " * documented /std:clatest C23 feature set does not include `nullptr` and the\n"
    " * required Windows builds compile this TU with cl.exe (C2065). ADR-1138. */"
)
NULLPTR_END = "/* NOLINTEND(modernize-use-nullptr) */"


def licence_block() -> str:
    # The tag is split so licence scanners do not read this literal as a header.
    tag = "SPDX-" + "License-Identifier"
    return f"/**\n *\n *  Copyright 2026 Lusoris\n *\n * {tag}: EUPL-1.2\n */\n"


def banner_comment() -> str:
    lines = BANNER.split("\n")
    body = "\n".join(" * " + line for line in lines)
    return "/*\n" + body + "\n */\n"


def doc_block(text: str, indent: str = "", extra: tuple[str, ...] = ()) -> str:
    """A `/** ... */` block wrapped to the column limit."""
    width = COLUMNS - len(indent) - 3
    lines = textwrap.wrap(text, width=width) if text else []
    lines += list(extra)
    if len(lines) == 1 and len(indent) + len(lines[0]) + 7 <= COLUMNS:
        return f"{indent}/** {lines[0]} */\n"
    body = "".join(f"{indent} * {line}\n".replace(" * \n", " *\n") for line in lines)
    return f"{indent}/**\n{body}{indent} */\n"


def field_type(field: Field) -> str:
    return SCALARS[field.type]


def type_spelling(api: Api, type_name: str) -> str:
    """The C type of a value (not a pointer to it)."""
    if type_name in SCALARS:
        return SCALARS[type_name]
    if type_name.startswith("foreign:"):
        return type_name.split(":", 1)[1]
    return type_name


# Spelling of a parameter per pass mode; `{t}` is the value type.
MODE_SPELLING = {
    "error": "VmafxError **",
    "out_handle": "{t} **",
    "out": "{t} *",
    "in_const": "const {t} *",
}


def param_decl(api: Api, param: Param) -> str:
    base = type_spelling(api, param.type)
    if param.mode in MODE_SPELLING:
        return MODE_SPELLING[param.mode].format(t=base) + param.name
    if api.is_struct(param.type):
        return f"const {base} *{param.name}"
    if api.is_handle(param.type) or param.type.startswith("foreign:"):
        return f"{base} *{param.name}"
    return pointer_join(base, param.name)


def pointer_join(c_type: str, name: str) -> str:
    """`const char *` + `x` -> `const char *x`; `int` + `x` -> `int x`."""
    if c_type.endswith("*"):
        return c_type + name
    return f"{c_type} {name}"


def return_spelling(api: Api, fn: Function) -> str:
    if fn.returns == "void":
        return "void"
    if fn.returns.startswith(("handle:", "foreign:")):
        return fn.returns.split(":", 1)[1] + " *"
    return type_spelling(api, fn.returns)


def packed(head: str, items: list[str], tail: str) -> str:
    """`head(item, item, ...)tail`, bin-packed and aligned after the parenthesis."""
    single = head + "(" + ", ".join(items) + ")" + tail
    if len(single) <= COLUMNS or not items:
        return single
    indent = " " * (len(head) + 1)
    lines: list[str] = []
    current = head + "("
    for position, item in enumerate(items):
        last = position == len(items) - 1
        piece = item + (")" + tail if last else ",")
        candidate = current + ("" if current.endswith("(") else " ") + piece
        if len(candidate) <= COLUMNS or current.endswith("("):
            current = candidate
            continue
        lines.append(current)
        current = indent + piece
    lines.append(current)
    return "\n".join(lines)


def assignment(lhs: str, callee: str, args: list[str]) -> str:
    """`lhs = callee(args);` as clang-format breaks it: after `=` when the call then fits."""
    single = f"{lhs} = {callee}(" + ", ".join(args) + ");"
    if len(single) <= COLUMNS:
        return single
    indent = " " * (len(lhs) - len(lhs.lstrip()) + 4)
    rest = f"{indent}{callee}(" + ", ".join(args) + ");"
    if len(rest) <= COLUMNS:
        return f"{lhs} =\n{rest}"
    return packed(f"{lhs} = {callee}", args, ";")


def declaration(api: Api, fn: Function, export: str) -> str:
    ret = return_spelling(api, fn)
    head = pointer_join(f"{export} {ret}", fn.name)
    params = [param_decl(api, p) for p in fn.params] or ["void"]
    return packed(head, params, ";")
